import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const _=JSON.parse('{"title":"Первый сеанс","description":"","frontmatter":{"pageId":"players/getting-started","contentRevision":1},"headers":[],"relativePath":"ru/players/getting-started.md","filePath":"ru/players/getting-started.md"}'),l={name:"ru/players/getting-started.md"};function s(n,a,o,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="первыи-сеанс" tabindex="-1">Первый сеанс <a class="header-anchor" href="#первыи-сеанс" aria-label="Permalink to &quot;Первый сеанс&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Проверь версию игры, установи Harmony и Rimlink, включи их в списке модов и перезапусти игру.</li><li>Открой <strong>Мультиплеер</strong>, добавь адрес и порт сервера, затем войди способом, разрешённым администратором.</li><li>Сверь новый отпечаток сертификата по независимому каналу. Устрани различия набора модов.</li><li>Создай колонию на общей планете: параметры мира задаёт сервер, выбирай свободное место.</li><li>Дождись появления поселенцев, начни игру. Перед выходом используй обычный выход в главное меню и дождись сохранения/отправки.</li><li>При следующем входе убедись, что сервер загрузил эту колонию. Только после этого начинай передачи и поездки.</li></ol><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не закрывай процесс принудительно во время отправки. Вход нового администратора может использоваться для создания мира; обычный игрок не должен создавать отдельную планету в обход серверного мира.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./install">Установка мода</a></li><li><a href="./connect">Подключение и вход</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',8)])])}const m=e(l,[["render",s]]);export{_ as __pageData,m as default};
